target.css:
:root {
  --ink: #152832;
  --muted: #69808a;
  --paper: #fcfcf7;
  --line: #d8e2df;
  --aqua: #36c5ba;
  --aqua-dark: #167d7a;
  --navy: #193e51;
  --lime: #d9ef62;
  --orange: #f29d55;
}

.wind-panel,
.wind-panel * {
  box-sizing: border-box;
}

.wind-panel {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 1.1px;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  margin-top: 4px;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.7px;
}

.live-dot {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-radius: 999px;
  background: var(--lime);
  color: var(--navy);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.live-dot span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--aqua-dark);
}

.main-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 10px;
  padding: 12px 16px;
}

.model-card {
  display: flex;
  align-items: center;
  grid-column: 1 / -1;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--navy);
  color: var(--paper);
}

.model-mark {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 10px;
  background: var(--aqua);
  color: var(--navy);
  font-size: 29px;
  line-height: 1;
  transform: rotate(45deg);
}

.model-meta .eyebrow {
  color: var(--aqua);
}

h2 {
  margin: 3px 0 4px;
  font-size: 15px;
  line-height: 1.1;
}

.model-meta > p:last-child {
  color: var(--line);
  font-size: 11px;
}

.run-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.stat {
  padding: 10px 7px;
  border-right: 1px solid var(--line);
}

.stat:last-child {
  border-right: 0;
}

.stat small {
  display: block;
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.stat strong {
  display: block;
  margin-top: 5px;
  color: var(--navy);
  font-size: 15px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.stat em {
  color: var(--aqua-dark);
  font-size: 9px;
  font-style: normal;
}

.readout {
  padding: 10px 11px;
  border-radius: 12px;
  background: var(--ink);
}

.readout .eyebrow {
  color: var(--aqua);
  margin-bottom: 8px;
}

.readout-row {
  display: flex;
  justify-content: space-between;
  color: var(--line);
  font-size: 10px;
  line-height: 1;
}

.readout-row b {
  color: var(--paper);
  font-size: 12px;
}

.meter {
  height: 5px;
  margin: 5px 0 9px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--navy);
}

.meter span {
  display: block;
  width: 74%;
  height: 100%;
  border-radius: inherit;
  background: var(--aqua);
}

.meter.drag {
  margin-bottom: 0;
}

.meter.drag span {
  width: 27%;
  background: var(--orange);
}

.footer-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
  border-top: 1px solid var(--line);
}

.calibration {
  color: var(--aqua-dark);
  font-size: 10px;
  font-weight: 700;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 7px 10px;
  background: var(--orange);
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
}

